from .client import SUPABASE_SERVICE_KEY, SUPABASE_URL, get_headers
import httpx


async def insert_petition_analysis(
    petition_id: int,
    detailed_summary: str,
):
    """Insert the detailed summary generated by the first LLM call."""

    if not SUPABASE_URL or not SUPABASE_SERVICE_KEY:
        raise RuntimeError("Missing Supabase credentials in .env")

    url = f"{SUPABASE_URL.rstrip('/')}/rest/v1/petition_analysis_v2"

    analysis = {
        "petition_id": petition_id,
        "detailed_summary": detailed_summary,
    }

    async with httpx.AsyncClient(timeout=15) as client:
        response = await client.post(
            url,
            headers=get_headers(),
            json=analysis,
        )

    response.raise_for_status()

    saved_analysis = response.json()

    if not saved_analysis:
        raise RuntimeError(
            "Supabase did not return the inserted analysis."
        )

    return saved_analysis[0]


async def update_petition_analysis(
    petition_id: int,
    officer_summary: str,
    ai_authority_id: int,
    ai_priority: str,
    confidence: float,
    reason: str,
):
    """Update the analysis using the second LLM call's output."""

    if not SUPABASE_URL or not SUPABASE_SERVICE_KEY:
        raise RuntimeError("Missing Supabase credentials in .env")

    url = f"{SUPABASE_URL.rstrip('/')}/rest/v1/petition_analysis_v2"

    analysis = {
        "officer_summary": officer_summary,
        "ai_authority_id": ai_authority_id,
        "ai_priority": ai_priority,
        "confidence": confidence,
        "reason": reason,
    }

    async with httpx.AsyncClient(timeout=15) as client:
        response = await client.patch(
            url,
            headers=get_headers(),
            params={"petition_id": f"eq.{petition_id}"},
            json=analysis,
        )

    response.raise_for_status()

    updated_analysis = response.json()

    if not updated_analysis:
        raise LookupError(
            f"No analysis found for petition ID {petition_id}."
        )

    return updated_analysis[0]
async def get_petition_analysis_by_id(petition_id: int):
    """Fetch the analysis for a specific petition from Supabase."""

    if not SUPABASE_URL or not SUPABASE_SERVICE_KEY:
        raise RuntimeError("Missing Supabase credentials in .env")

    url = f"{SUPABASE_URL.rstrip('/')}/rest/v1/petition_analysis_v2"

    async with httpx.AsyncClient(timeout=15) as client:
        response = await client.get(
            url,
            headers=get_headers(),
            params={
                "select": "*",
                "petition_id": f"eq.{petition_id}",
                "limit": 1,
            },
        )

    response.raise_for_status()

    analyses = response.json()

    if not analyses:
        return None

    return analyses[0]
